func contribCell(count int) string {
	switch {
	case count == 0:
		return "contrib-0"
	case count <= 3:
		return "contrib-1"
	case count <= 6:
		return "contrib-2"
	case count <= 9:
		return "contrib-3"
	default:
		return "contrib-4"
	}
}

